INSERT INTO "documents" VALUES('interactions','stream:practice-9276b92f-8067-4c90-9f89-061f980c03dc','{"id": "stream:practice-9276b92f-8067-4c90-9f89-061f980c03dc", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$. Find $P(\\\\phi)$ and when it is zero.\", \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 3}');
INSERT INTO "documents" VALUES('practice_tasks','practice-9276b92f-8067-4c90-9f89-061f980c03dc:0','{"id": "practice-9276b92f-8067-4c90-9f89-061f980c03dc:0", "concept_id": "paths", "question": "Two paths have amplitudes $1/2$ and $e^{i\\phi}/2$. Find $P(\\phi)$ and when it is zero.", "origin": "self_created", "source_refs": [], "status": "attempted", "history": [{"action": "hint", "feedback": "Expand $|z|^2 = z^* z$ first."}, {"action": "assess", "feedback": "$P(\\phi)$ is right; check when the cosine is $-1$.", "outcome": "needs_work", "evidence_id": "practice-evidence:practice-3b6c0860-0ab7-4cbe-9fae-7badbbdd4989", "kind": "needs_work", "answer": "P = (1 + cos phi)/2, zero at phi = 0."}, {"action": "assess", "feedback": "Right: $P = (1 + \\cos\\phi)/2$, zero at $\\phi = \\pi$.", "outcome": "passed", "evidence_id": "practice-evidence:practice-ff7a025f-8557-4fcf-bd23-8c760f777c39", "kind": "hinted", "answer": "P = (1 + cos phi)/2, zero at phi = pi."}]}');
