18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "route": [{"id": "paths", "title": "Adding path amplitudes"}, {"id": "states", "title": "States and global phase", "prerequisites": ["paths"]}, {"id": "outcomes", "title": "Measurement outcomes", "prerequisites": ["states"]}], "session": {"position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "context": {"concept": {"id": "paths", "title": "Adding path amplitudes", "objective": "Predict interference from two amplitudes", "links": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "exercises": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "question": "Find the probability for equal amplitudes."}]}, "chapter": {"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"], "index": 0, "total": 2}, "position": {"concept_id": "paths", "goal": "Predict interference", "next_step": "Start the lesson", "progress": ""}, "prerequisites": [], "next_concept_id": "states", "sources": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2", "id": "line-2", "locator": {"line": 2}, "text": "Two paths reach the same detector, each with a complex amplitude.", "stale": false}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3", "id": "line-3", "locator": {"line": 3}, "text": "The total amplitude is the sum of the path amplitudes.", "stale": false}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4", "id": "line-4", "locator": {"line": 4}, "text": "The probability is the squared magnitude of the total amplitude.", "stale": false}]}, "active_branch": null, "due_explanations": [], "unanswered_questions": [], "recent_interactions": [{"id": "stream-user:84fe9a72-f503-4fc0-842f-2109d40d6a59", "role": "user", "text": "Teach this section fully around the current goal: start with the intuition behind its core question, then give the precise definitions, statements or methods with their conditions and the necessary derivations, and include a worked example.", "concept_id": "paths", "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 1}, {"id": "stream:84fe9a72-f503-4fc0-842f-2109d40d6a59", "role": "assistant", "text": "## Adding path amplitudes\n\nEach path carries a complex amplitude $a$ or $b$.\n\n$$P = |a + b|^2 = |a|^2 + |b|^2 + 2\\,\\mathrm{Re}(a^* b)$$", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 2}, {"id": "stream:practice-9276b92f-8067-4c90-9f89-061f980c03dc", "role": "assistant", "text": "{\"questions\": [{\"question\": \"Two paths have amplitudes $1/2$ and $e^{i\\\\phi}/2$. Find $P(\\\\phi)$ and when it is zero.\", \"origin\": \"self_created\", \"source_refs\": []}]}", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 3}, {"id": "stream-user:branch:cross-term", "role": "user", "text": "Why is the cross term 2 Re(a* b)?", "concept_id": "paths", "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 4}, {"id": "stream:branch:cross-term", "role": "assistant", "text": "Because $|z|^2 = z^* z$, the cross terms give $2\\,\\mathrm{Re}(a^* b)$.\n<teaching-decision>{\"depth\": \"short\", \"category\": \"local\", \"rationale\": \"Local algebra\", \"suggest_supplement\": false, \"supplement_goal\": \"\"}</teaching-decision>", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 5}, {"id": "stream-user:reply:cross-term:42fd46b2-925c-4e75-a704-09e68f9cfb0e", "role": "user", "text": "And when both amplitudes are real?", "concept_id": "paths", "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 6}, {"id": "stream:reply:cross-term:42fd46b2-925c-4e75-a704-09e68f9cfb0e", "role": "assistant", "text": "## Adding path amplitudes\n\nEach path carries a complex amplitude $a$ or $b$.\n\n$$P = |a + b|^2 = |a|^2 + |b|^2 + 2\\,\\mathrm{Re}(a^* b)$$", "concept_id": "paths", "supplied_source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_refs": [{"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-2"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-3"}, {"source_id": "src-ed653eaa6bca0a1ae76199b5", "revision": "363a18ff401bcf835bdf439f1d8372e9245ab8e8fcbec5a2f941d2a8789e7645", "unit_id": "line-4"}], "source_context_concept_id": "paths", "sequence": 7}]}, "language": "en", "chapters": [{"id": "superposition", "title": "Superposition", "concept_ids": ["paths", "states"]}, {"id": "measurement", "title": "Measurement", "concept_ids": ["outcomes"]}], "learner_profile": {"goal": "Understand interference and measurement", "depth": "standard", "prerequisites": [{"topic": "Complex numbers", "level": "some"}], "focus": "Problem solving"}}, "attempt": 1, "status": "completed", "text": "{\"feedback\": \"Expand $|z|^2 = z^* z$ first.\"}", "final_text": "{\"feedback\": \"Expand $|z|^2 = z^* z$ first.\"}", "sequence": 3, "started_at": 1795105972.2606544, "metrics": {"first_delta_s": 0.0071942806243896484, "full_s": 0.017172574996948242, "save_s": 0.00016979499923763797}, "attempts": [], "resume_requests": []}');
